/* ---------- BlurText (reactbits-effects/text-effects.jsx #2) ---------- */
function BlurText({ text, className = "", delay = 70, style = {} }) {
  return (
    <span className={className} style={style}>
      {text.split(" ").map((word, i) => (
        <span
          key={i}
          style={{
            display: "inline-block",
            filter: "blur(10px)",
            opacity: 0,
            animation: "rb-blur-in 0.7s ease forwards",
            animationDelay: `${i * delay}ms`,
            marginRight: "0.28em",
          }}
        >
          {word}
        </span>
      ))}
      <style>{`@keyframes rb-blur-in{to{filter:blur(0);opacity:1}}`}</style>
    </span>
  );
}

/* ---------- ScrollReveal (reactbits-effects/misc-effects.jsx #3, extendido con extraDelay) ---------- */
function ScrollReveal({ children, className = "", extraDelay = 0 }) {
  const ref = useRef(null);
  const [visible, setVisible] = useState(false);
  useEffect(() => {
    const obs = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) setVisible(true);
      },
      { threshold: 0.15 }
    );
    if (ref.current) obs.observe(ref.current);
    return () => obs.disconnect();
  }, []);
  return (
    <div
      ref={ref}
      className={className}
      style={{
        opacity: visible ? 1 : 0,
        transform: visible ? "translateY(0)" : "translateY(36px)",
        transition: `opacity 0.7s ease ${extraDelay}ms, transform 0.7s ease ${extraDelay}ms`,
      }}
    >
      {children}
    </div>
  );
}

/* ---------- Marquee (reactbits-effects/misc-effects.jsx #1) ---------- */
function Marquee({ items, className = "" }) {
  const track = [...items, ...items];
  return (
    <div className={"overflow-hidden whitespace-nowrap " + className}>
      <div style={{ display: "inline-flex", animation: "rb-marquee 22s linear infinite" }}>
        {track.map((it, i) => (
          <span
            key={i}
            className="font-mono text-xs mx-6"
            style={{ color: C.parchmentDim, letterSpacing: "0.08em" }}
          >
            {it}
          </span>
        ))}
      </div>
      <style>{`@keyframes rb-marquee{from{transform:translateX(0)}to{transform:translateX(-50%)}}`}</style>
    </div>
  );
}

/* ---------- NoiseOverlay (reactbits-effects/misc-effects.jsx #7) ---------- */
function NoiseOverlay({ opacity = 0.05, className = "" }) {
  return (
    <svg className={"absolute inset-0 w-full h-full pointer-events-none " + className} style={{ opacity }}>
      <filter id="rb-noise-overlay">
        <feTurbulence type="fractalNoise" baseFrequency="0.9" numOctaves="2" stitchTiles="stitch" />
      </filter>
      <rect width="100%" height="100%" filter="url(#rb-noise-overlay)" />
    </svg>
  );
}

/* ---------- CountUp (reactbits-effects/text-effects.jsx #8, con separador de miles) ---------- */
function CountUp({ to, duration = 1700, className = "", suffix = "", prefix = "" }) {
  const [val, setVal] = useState(0);
  const ref = useRef(null);
  const [started, setStarted] = useState(false);

  useEffect(() => {
    const obs = new IntersectionObserver(([entry]) => {
      if (entry.isIntersecting) setStarted(true);
    });
    if (ref.current) obs.observe(ref.current);
    return () => obs.disconnect();
  }, []);

  useEffect(() => {
    if (!started) return;
    let start;
    const step = (ts) => {
      if (!start) start = ts;
      const progress = Math.min((ts - start) / duration, 1);
      setVal(Math.floor(progress * to));
      if (progress < 1) requestAnimationFrame(step);
    };
    requestAnimationFrame(step);
  }, [started, to, duration]);

  return (
    <span ref={ref} className={className}>
      {prefix}
      {val.toLocaleString("es-ES")}
      {suffix}
    </span>
  );
}

/* ---------- RosterCard: TiltCard (reactbits-effects/cards.jsx #2) adaptado con imagen ---------- */
function RosterCard({ img, name, rarity, desc, rarityColor }) {
  const ref = useRef(null);
  const [style, setStyle] = useState({});
  return (
    <div
      ref={ref}
      onMouseMove={(e) => {
        const rect = ref.current.getBoundingClientRect();
        const px = (e.clientX - rect.left) / rect.width - 0.5;
        const py = (e.clientY - rect.top) / rect.height - 0.5;
        setStyle({ transform: `perspective(700px) rotateX(${-py * 10}deg) rotateY(${px * 10}deg) scale(1.02)` });
      }}
      onMouseLeave={() => setStyle({ transform: "perspective(700px) rotateX(0) rotateY(0) scale(1)" })}
      className="relative rounded-2xl p-5 overflow-hidden"
      style={{
        ...style,
        background: C.panel,
        border: `1px solid ${C.line}`,
        transition: "transform 0.2s ease-out",
      }}
    >
      <div
        style={{
          position: "absolute",
          inset: 0,
          background: `radial-gradient(120% 90% at 50% 0%, ${rarityColor}26, transparent 65%)`,
          pointerEvents: "none",
        }}
      />
      <div className="relative flex flex-col items-center text-center">
        <div style={{ height: 168, display: "flex", alignItems: "center", justifyContent: "center" }}>
          <img
            src={img}
            alt={name}
            style={{ maxHeight: "100%", maxWidth: "100%", filter: "drop-shadow(0 12px 18px rgba(0,0,0,0.5))" }}
          />
        </div>
        <span
          className="font-mono text-xs uppercase mt-4 px-3 py-1 rounded-full"
          style={{ color: rarityColor, border: `1px solid ${rarityColor}66`, letterSpacing: "0.08em" }}
        >
          {rarity}
        </span>
        <h3 className="font-display text-xl mt-3" style={{ color: C.parchment }}>
          {name}
        </h3>
        <p className="font-body text-sm mt-2" style={{ color: C.parchmentDim, lineHeight: 1.5 }}>
          {desc}
        </p>
      </div>
    </div>
  );
}

